// Forked from: https://www.shadertoy.com/view/M3dfDn

#define TAU 6.2831853071

// Number of dots / tau...
float scale = 32.0 / TAU;

float disc(vec2 pos, float s)
{
    return smoothstep(s + .03, s, length(pos));
}

vec2 logPolar(vec2 p)
{
	p = vec2( log(length(p)), atan(p.y, p.x) );
	return p;
}

float dots(vec2 p)
{
    // Calc radius with a sine wave on polar y (angle) and time...
    float rad = (sin((p.y * 0.333 + iTime * 0.5) * TAU) + 1.0) * 0.2;
    p *= scale;
    // Position(s)...
    vec2 q = fract(p) - 0.5;
    float ret = disc(q, rad);
    // Now remove dots outside of desired ring...
    // You can move this in and out
    ret *= step(-1., p.x) * step(p.x, 0.);
	return ret;
}

void mainImage( out vec4 outCol, in vec2 inCoor )
{
    // Normalise coords and adjust aspect...
    vec2 uv = (2.0 * inCoor - iResolution.xy) / min(iResolution.y, iResolution.x);

    // Cartesian to Log Polar...
    vec2 pol  = logPolar(uv);
    // Use polar for dot pattern...
    float c = dots(pol);

    outCol = vec4(c,c,c,1);
}
